17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	import java.util.Locale;
27	import java.util.Map;
28	import java.util.regex.Pattern;
29	
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
42	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
43	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
71	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization, keyed by the
78	     * upper-cased abbreviation.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
81	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        validateRequiredFields(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
133	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
134	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
135	        rejectDuplicateTelephone(telephone);
136	        owner.setTelephone(telephone);
137	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
138	        if (owner.getRegistrationDate() == null) {
139	            owner.setRegistrationDate(LocalDate.now());
140	        }
141	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
142	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        this.clinicService.saveOwner(owner);
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    /**
152	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
153	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
154	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
155	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
156	     *
157	     * @param city     the owner's city
158	     * @param lastName the owner's last name
159	     * @return the assigned customer code
160	     */
161	    private String nextCustomerCode(String city, String lastName) {
162	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
163	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
164	        int sequence = (int) this.clinicService.findAllOwners().stream()
165	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
166	            .count() + 1;
167	        return String.format("%s-%s-%04d", city3, last3, sequence);
168	    }
169	
170	    /**
171	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
172	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
173	     *
174	     * @param customerCode     the owner's assigned customer code
175	     * @param registrationDate the owner's registration date
176	     * @return the assigned membership number
177	     */
178	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
179	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
180	    }
181	
182	    /**
183	     * Counts the existing owners that already share the given firstName and lastName, compared
184	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
185	     * the owners that pre-existed this create.
186	     *
187	     * @param firstName the new owner's first name
188	     * @param lastName  the new owner's last name
189	     * @return the number of existing namesakes
190	     */
191	    private int countNamesakes(String firstName, String lastName) {
192	        return (int) this.clinicService.findAllOwners().stream()
193	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
194	                && equalsIgnoreCase(existing.getLastName(), lastName))
195	            .count();
196	    }
197	
198	    private boolean equalsIgnoreCase(String a, String b) {
199	        return a == null ? b == null : a.equalsIgnoreCase(b);
200	    }
201	
202	    /**
203	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
204	     * offending field so the client learns about all of them at once.
205	     *
206	     * @param ownerFieldsDto the submitted owner fields
207	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
208	     *                                     missing or blank
209	     */
210	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
211	        List<String> errors = new ArrayList<>();
212	        if (isBlank(ownerFieldsDto.getFirstName())) {
213	            errors.add("firstName");
214	        }
215	        if (isBlank(ownerFieldsDto.getLastName())) {
216	            errors.add("lastName");
217	        }
218	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
219	            errors.add("address");
220	        }
221	        if (isBlank(ownerFieldsDto.getCity())) {
222	            errors.add("city");
223	        }
224	        if (isBlank(ownerFieldsDto.getTelephone())) {
225	            errors.add("telephone");
226	        }
227	        if (!errors.isEmpty()) {
228	            throw new MissingOwnerFieldsException(errors);
229	        }
230	    }
231	
232	    private boolean isBlank(String value) {
233	        return value == null || value.isBlank();
234	    }
235	
236	    /**
237	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
238	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
239	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
240	     * followed by 8 to 15 digits.
241	     *
242	     * @param telephone the raw telephone value as submitted
243	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
244	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
245	     */
246	    private String normalizeTelephone(String telephone) {
247	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
248	        String nationalSignificantNumber;
249	        if (cleaned.startsWith("+")) {
250	            nationalSignificantNumber = cleaned.substring(1);
251	        } else {
252	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
253	            nationalSignificantNumber = "61" + national;
254	        }
255	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
256	            throw new InvalidTelephoneException(telephone);
257	        }
258	        return "+" + nationalSignificantNumber;
259	    }
260	
261	    /**
262	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
263	     * value is treated as absent and returns {@code null}); when present the value must be a
264	     * syntactically valid address, and is stored and returned lower-cased.
265	     *
266	     * @param email the raw email value as submitted, may be {@code null}
267	     * @return the lower-cased email, or {@code null} when none was supplied
268	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
269	     */
270	    private String normalizeEmail(String email) {
271	        if (email == null || email.isBlank()) {
272	            return null;
273	        }
274	        String normalized = email.trim().toLowerCase();
275	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
276	            throw new InvalidEmailException(email);
277	        }
278	        return normalized;
279	    }
280	
281	    /**
282	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
283	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
284	     * comparison, so numbers that differ only in formatting still count as duplicates.
285	     *
286	     * @param e164Telephone the E.164 telephone of the owner being created
287	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
288	     */
289	    private void rejectDuplicateTelephone(String e164Telephone) {
290	        boolean inUse = this.clinicService.findAllOwners().stream()
291	            .map(Owner::getTelephone)
292	            .filter(existing -> existing != null)
293	            .map(this::toComparableTelephone)
294	            .filter(existing -> existing != null)
295	            .anyMatch(e164Telephone::equals);
296	        if (inUse) {
297	            throw new DuplicateTelephoneException(e164Telephone);
298	        }
299	    }
300	
301	    /**
302	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
303	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
304	     * than aborting the whole create.
305	     */
306	    private String toComparableTelephone(String telephone) {
307	        try {
308	            return normalizeTelephone(telephone);
309	        } catch (InvalidTelephoneException ex) {
310	            return null;
311	        }
312	    }
313	
314	    /**
315	     * Applies the household rule to an owner being created. An owner belongs to the same household
316	     * as an existing owner when their lastName and address both match (compared case-insensitively
317	     * with runs of whitespace collapsed to a single space).
318	     *
319	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
320	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
321	     * does, the new owner and every existing owner in the household are assigned the same stable
322	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
323	     *
324	     * @param owner            the owner being created
325	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
326	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
327	     *                                     the request did not opt in with {@code sharesHousehold=true}
328	     */
329	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
330	        String lastNameKey = toHouseholdKey(owner.getLastName());
331	        String addressKey = toHouseholdKey(owner.getAddress());
332	        List<Owner> household = this.clinicService.findAllOwners().stream()
333	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
334	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
335	            .toList();
336	        if (household.isEmpty()) {
337	            return;
338	        }
339	        if (!Boolean.TRUE.equals(sharesHousehold)) {
340	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
341	        }
342	        String householdId = householdId(lastNameKey, addressKey);
343	        owner.setHouseholdId(householdId);
344	        for (Owner existing : household) {
345	            if (!householdId.equals(existing.getHouseholdId())) {
346	                existing.setHouseholdId(householdId);
347	                this.clinicService.saveOwner(existing);
348	            }
349	        }
350	    }
351	
352	    /**
353	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
354	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
355	     * lastName and address keys. Being a pure function of the household, every owner in it derives
356	     * the same value regardless of creation order.
357	     *
358	     * @param lastNameKey the normalized household lastName key
359	     * @param addressKey  the normalized household address key
360	     * @return the household identifier
361	     */
362	    private String householdId(String lastNameKey, String addressKey) {
363	        try {
364	            byte[] digest = MessageDigest.getInstance("SHA-256")
365	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
366	            StringBuilder hex = new StringBuilder(digest.length * 2);
367	            for (byte b : digest) {
368	                hex.append(String.format("%02x", b));
369	            }
370	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
371	        } catch (NoSuchAlgorithmException ex) {
372	            throw new IllegalStateException("SHA-256 not available", ex);
373	        }
374	    }
375	
376	    /**
377	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
378	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
379	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
380	     * string.
381	     */
382	    private String toHouseholdKey(String value) {
383	        if (value == null) {
384	            return "";
385	        }
386	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
387	    }
388	
389	    /**
390	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
391	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
392	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
393	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
394	     * value, or one that is blank once trimmed, normalizes to an empty string.
395	     *
396	     * @param address the raw address value as submitted, may be {@code null}
397	     * @return the normalized address, or an empty string when none was supplied
398	     */
399	    private String normalizeAddress(String address) {
400	        if (address == null) {
401	            return "";
402	        }
403	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
404	        if (collapsed.isEmpty()) {
405	            return "";
406	        }
407	        String[] tokens = collapsed.split(" ");
408	        StringBuilder normalized = new StringBuilder(collapsed.length());
409	        for (int i = 0; i < tokens.length; i++) {
410	            if (i > 0) {
411	                normalized.append(' ');
412	            }
413	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
414	        }
415	        return normalized.toString();
416	    }
417	
418	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
419	    @Override
420	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
421	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
422	        if (currentOwner == null) {
423	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
424	        }
425	        currentOwner.setAddress(ownerFieldsDto.getAddress());
426	        currentOwner.setCity(ownerFieldsDto.getCity());
427	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
428	        currentOwner.setLastName(ownerFieldsDto.getLastName());
429	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
430	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
431	        this.clinicService.saveOwner(currentOwner);
432	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
433	    }
434	
435	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
436	    @Transactional
437	    @Override
438	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
439	        Owner owner = this.clinicService.findOwnerById(ownerId);
440	        if (owner == null) {
441	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
442	        }
443	        this.clinicService.deleteOwner(owner);
444	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
445	    }
446	
447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Override
449	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
450	        Owner owner = this.clinicService.findOwnerById(ownerId);
451	        if (owner == null) {
452	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
453	        }
454	        HttpHeaders headers = new HttpHeaders();
455	        Pet pet = petMapper.toPet(petFieldsDto);
456	        owner.setId(ownerId);
457	        pet.setOwner(owner);
458	        pet.getType().setName(null);
459	        this.clinicService.savePet(pet);
460	        PetDto petDto = petMapper.toPetDto(pet);
461	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
462	            .buildAndExpand(pet.getId()).toUri());
463	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
464	    }
465	
466	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
467	    @Override
468	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
469	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
470	        if (currentOwner != null) {
471	            Pet currentPet = this.clinicService.findPetById(petId);
472	            if (currentPet != null) {
473	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
474	                currentPet.setName(petFieldsDto.getName());
475	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
476	                this.clinicService.savePet(currentPet);
477	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
478	            }
479	        }
480	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
481	    }
482	
483	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
484	    @Override
485	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
486	        HttpHeaders headers = new HttpHeaders();
487	        Visit visit = visitMapper.toVisit(visitFieldsDto);
488	        Pet pet = new Pet();
489	        pet.setId(petId);
490	        visit.setPet(pet);
491	        this.clinicService.saveVisit(visit);
492	        VisitDto visitDto = visitMapper.toVisitDto(visit);
493	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
494	            .buildAndExpand(visit.getId()).toUri());
495	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
496	    }
497	
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
502	        Owner owner = this.clinicService.findOwnerById(ownerId);
503	        if (owner != null) {
504	            Pet pet = owner.getPet(petId);
505	            if (pet != null) {
506	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
507	            }
508	        }
509	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
510	    }
511	}
